// Changes: FAKE_LINE_BREAK is an EOL_TOKEN, as the lexer emits inside
// parentheses.
Token fake_next(Ctx* ctx, void* state) {
  (void)ctx;
  FakeSource* source = state;
  if (source->position >= source->count)
    return (Token){.type = EOF_TOKEN, .line = source->breaks + 1};

  Token token = source->tokens[source->position++];
  if (token.type == FAKE_LINE_BREAK)
    token.type = EOL_TOKEN;
  if (token.line == 0)
    token.line = source->breaks + 1;
  if (token.type == EOL_TOKEN)
    source->breaks++;
  if (token.type == FAKE_LEXICAL_ERROR)
    THROW(E_LEXER_ERROR, "fake lexical error");
  if (fake_has_text(token.type)) {
    char* copy = malloc(strlen(token.value.text) + 1);
    strcpy(copy, token.value.text);
    token.value.text = copy;
    // AI generated by: Claude Code (claude-opus-5-5)
    // Prompt: "on the branch feat/implement-lexer there should be a function
    // for next token implemented, could you look at it and prepare the parser
    // for it. do not merge its code only looks at it."
    // Changes: heap text is marked TEXT, as the lexer does.
    token.value_type = TEXT;
  }
  return token;
}
